namespace SqliteVector.Net.Storage; using System; public enum StorageFailurePoint { None = 0, AfterPhysicalCommitBeforeLogicalCommit = 1, InsideLogicalTransaction = 2, AfterLogicalCommitBeforeSnapshotPublish = 3 } public static class FailureInjector { public static Action<StorageFailurePoint>? Hook { get; set; } public static void Inject(StorageFailurePoint point) { Hook?.Invoke(point); } }
